[SuppressBPWarning('BPParameterNotUsed', 'Parameter e required in signature'),
FormControlEventHandler(formControlStr(SalesTable, AVAShowDocTextImage), FormControlEventType::Clicked)]
public static void AVAShowDocTextImage_OnClicked(FormControl sender, FormControlEventArgs e)
{
    FormDataSource      formDataSource;
    FormControl         formControl;
    SalesLine           salesLine;
    FormRun             formRun;

    formControl         = sender;
    formRun             = sender.formRun();
    formDataSource      = formRun.dataSource(tableStr(SalesLine));
    salesLine           = formDataSource.cursor();
    if(salesLine.RecId)
    {
        Docu::Instance().note(formRun);
    }
}

/// <summary>
/// AVA 
/// </summary>
/// <param name="sender">FormDataSource SalesTable</param>
/// <param name="e">FormDataSourceEventArgs</param>
[SuppressBPWarning('BPParameterNotUsed', 'Parameter e required in signature'),
    FormDataSourceEventHandler(formDataSourceStr(SalesTable, SalesTable), FormDataSourceEventType::Activated)]
public static void SalesTable_OnActivated(FormDataSource sender, FormDataSourceEventArgs e)
{
    SalesTable                      salesTable = sender.cursor();
    AVASalesInfoFields              custInfoFields;
    KCS_SOCSalesTableInfoFields     infoFields;
    KCS_ChainGroupInfoFields        chainGroupInfoFields;
    Dialog                          dialog;
    FormBuildDesign formBuildDesign;
    FormBuildStringControl  SalesInfoTxt, chainInfoTxt, Info1Txt;
    infoFields                    = KCS_SOCSalesTableInfoFields::find(AVATableInfoFieldTypes::Sales, salesTable.SalesId, true);
    chainGroupInfoFields          = KCS_ChainGroupInfoFields::find(salesTable.KCS_ChainId);
    boolean isThirdPartyGalvOrder;

    //der Dialog soll nur bei in der Maske neu erstellten Aufträgen erscheinen
    if (salesTable.SalesId && !salesTable.AVAhasLines())
    {
        if (!infoFields.InfoField2Finished && infoFields.InfoField2)
        {
            custInfoFields                         = AVASalesInfoFields::find(salesTable.custTable_CustAccount().Party);
            dialog = new Dialog("@NDX:NDAConfirmInfo");
            formBuildDesign = dialog.formBuildDesign();
            salesInfotxt = formBuildDesign.addControl(FormControlType::String, "@NDX:NXACustomerInfo");
            SalesInfoTxt.text(custInfoFields.InfoField2);
            SalesInfoTxt.label("@NDX:NXACustomerInfo");
            SalesInfoTxt.displayHeight(10);
            SalesInfoTxt.width(-1, 1);
            SalesInfoTxt.allowEdit(false);
            chainInfoTxt = formBuildDesign.addControl(FormControlType::String, "@NDX:NXAChainInfo");
            chainInfoTxt.label("@NDX:NXAChainInfo");
            chainInfoTxt.text(chainGroupInfoFields.InfoField2);
            chainInfoTxt.width(-1, 1);
            chainInfoTxt.displayHeight(10);
            chainInfoTxt.allowEdit(false);
            Info1Txt = formBuildDesign.addControl(FormControlType::String, "@NDX:NXACustInfo1");
            Info1Txt.label("@NDX:NXACustInfo1");
            Info1Txt.text(custInfoFields.InfoField1);
            Info1Txt.width(-1, 1);
            Info1Txt.displayHeight(10);
            Info1Txt.allowEdit(false);
            dialog.run();
            if (dialog.closedOk())
            {
                ttsBegin;
                infoFields.InfoField2Finished         = NoYes::Yes;
                infoFields.InfoField2FinishedUser     = curuserid();
                infoFields.InfoField2FinishedDateTime = DateTimeUtil::getSystemDateTime();
                infoFields.update();
                ttscommit;
            }
        }
    }
    if (salesTable.AVARepPckSlipNum)
    {
        sender.formRun().design().controlName(formControlStr(SalesTable, AVAUpdateRackDiscount)).enabled(False);
    }
    else
    {
        sender.formRun().design().controlName(formControlStr(SalesTable, AVAUpdateRackDiscount)).enabled(true);
    }

    isThirdPartyGalvOrder = SalesOrigin::find(salesTable.SalesOriginId).AVAThirdPartyGalvBatchId;

    sender.formRun().design().controlName(formControlStr(salesTable, AVAThirdPartyGalvanizing)).enabled(isThirdPartyGalvOrder);
}

/// <summary>
///  AVA/WEN/2025/03/06 AVA_013113_IC_PAInfo
/// </summary>
/// <param name = "sender">FormDataObject</param>
/// <param name = "e">FormDataFieldEventArgs</param>
[   SuppressBPWarning('BPParameterNotUsed', 'Parameter e required in signature'),
    FormDataFieldEventHandler(formDataFieldStr(SalesTable, SalesLine, ItemId), FormDataFieldEventType::Modified)]
public static void ItemId_OnModified(FormDataObject sender, FormDataFieldEventArgs e)
{
    FormDataSource salesline_ds = sender.datasource();
    SalesLine salesLine = salesline_ds.cursor();
    salesline_ds.object(fieldNum(SalesLine, NDX_PAInfo)).allowEdit(salesLine.inventTable().AVAPAInfo || salesLine.inventTable().NDXReqGroupCovRuleIsReq());
}

